defects.code:
PROCEDURE @@proc@@ (p_text IN VARCHAR2) IS
    l_d DATE;
BEGIN
    l_d := TO_DATE(p_text); -- @expect
    IF l_d > SYSDATE THEN
        RAISE_APPLICATION_ERROR(-20010, 'date in the future');
    END IF;
    @@proc2@@(l_d);
END @@proc@@;

FUNCTION @@proc@@ (p_code IN VARCHAR2) RETURN BOOLEAN IS
    l_limit NUMBER := @@num@@;
BEGIN
    IF p_code = l_limit THEN -- @expect
        RETURN TRUE;
    END IF;
    RETURN FALSE;
END @@proc@@;

PROCEDURE @@proc@@ (p_amount IN NUMBER) IS
    l_num NUMBER;
BEGIN
    l_num := p_amount * 2;
    IF l_num = '@@str@@' THEN -- @expect
        @@proc2@@(l_num);
    END IF;
END @@proc@@;

PROCEDURE @@proc@@ IS
    l_str VARCHAR2(10) := '0';
BEGIN
    WHILE l_str < 100 LOOP -- @expect
        l_str := TO_CHAR(TO_NUMBER(l_str) + 10);
        @@proc2@@(l_str);
    END LOOP;
END @@proc@@;

FUNCTION @@proc@@ (p_when IN DATE) RETURN VARCHAR2 IS
    l_date  DATE := p_when;
    l_label VARCHAR2(20);
BEGIN
    l_label := CASE
                   WHEN l_date = '2020-01-01' THEN 'legacy' -- @expect
                   ELSE 'current'
               END;
    RETURN l_label;
END @@proc@@;

negatives.code:
FUNCTION @@proc@@ (p_qty IN NUMBER) RETURN VARCHAR2 IS
    l_limit NUMBER := 100;
BEGIN
    IF p_qty > 0 AND p_qty < 500 THEN
        RETURN 'normal';
    ELSIF l_limit >= 25 THEN
        RETURN 'capped';
    END IF;
    RETURN 'none';
END @@proc@@;

PROCEDURE @@proc@@ (p_text IN VARCHAR2) IS
    l_d  DATE;
    l_ts TIMESTAMP;
BEGIN
    l_d := TO_DATE(p_text, 'DD.MM.YYYY');
    l_ts := TO_TIMESTAMP(p_text || ' 00:00:00', 'DD.MM.YYYY HH24:MI:SS');
    @@proc2@@(l_d, l_ts);
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    l_status @@tab@@.@@col@@%TYPE;
    l_amount @@tab@@.@@col2@@%TYPE;
BEGIN
    @@proc2@@(p_id, l_status, l_amount);
    IF l_status = 'OPEN' THEN
        @@proc2@@(p_id, l_status, l_amount);
    END IF;
    IF l_amount = 'none' THEN
        @@proc2@@(p_id, l_status, l_amount);
    END IF;
END @@proc@@;

FUNCTION @@proc@@ (p_a IN VARCHAR2, p_b IN VARCHAR2) RETURN BOOLEAN IS
    l_norm VARCHAR2(50) := UPPER(TRIM(p_a));
BEGIN
    IF l_norm = p_b THEN
        RETURN TRUE;
    ELSIF p_a != l_norm THEN
        RETURN FALSE;
    END IF;
    RETURN NULL;
END @@proc@@;

FUNCTION @@proc@@ (p_text IN VARCHAR2, p_num IN NUMBER) RETURN BOOLEAN IS
BEGIN
    IF p_num = LENGTH(p_text) THEN
        RETURN TRUE;
    ELSIF p_num = SUBSTR(p_text, 1, 3) THEN
        RETURN FALSE;
    END IF;
    RETURN NULL;
END @@proc@@;
